import numpy as np
from gensim import matutils
from numpy import dot, array

# Symbolic constants to replace magic numbers
LOG_BASE = 10  # Assuming base 10 log, but np.log is natural log. Keeping np.log as per original.
NO_OF_UNITS = 1  # Used in IDF smoothing formula: log((total + 1) / (count + 1))

class VectorUtil:
    @staticmethod
    def similarity(vector_1, vector_2):
        return dot(matutils.unitvec(vector_1), matutils.unitvec(vector_2))

    @staticmethod
    def cosine_similarities(vector_1, vectors_all):
        vector_1_norm = np.linalg.norm(vector_1)
        vectors_all_norms = np.linalg.norm(vectors_all, axis=1)
        dot_products = dot(vectors_all, vector_1)
        similarities = dot_products / (vector_1_norm * vectors_all_norms)
        return similarities

    @staticmethod
    def n_similarity(vector_list_1, vector_list_2):
        if not VectorUtil._are_non_empty_lists(vector_list_1, vector_list_2):
            raise ZeroDivisionError('At least one of the passed list is empty.')
        return VectorUtil._compute_concept_similarity(VectorUtil._get_unitvec_average(vector_list_1),
                                                       VectorUtil._get_unitvec_average(vector_list_2))

    @staticmethod
    def _are_non_empty_lists(vector_list_1, vector_list_2):
        return len(vector_list_1) > 0 and len(vector_list_2) > 0

    @staticmethod
    def _get_unitvec_average(vector_list):
        return matutils.unitvec(array(vector_list).mean(axis=0))

    @staticmethod
    def _compute_concept_similarity(unitvec_1, unitvec_2):
        return dot(unitvec_1, unitvec_2)

    @staticmethod
    def compute_idf_weight_dict(total_num, number_dict):
        counts_and_keys = VectorUtil._extract_counts_and_keys(number_dict)
        idf_weights = VectorUtil._compute_idf_weights(total_num, counts_and_keys)
        return VectorUtil._build_weight_dict(idf_weights, number_dict)

    @staticmethod
    def _extract_counts_and_keys(number_dict):
        return list(number_dict.values()), list(number_dict.keys())

    @staticmethod
    def _compute_idf_weights(total_num, counts):
        a = np.array(counts)
        return np.log((total_num + NO_OF_UNITS) / (a + NO_OF_UNITS))

    @staticmethod
    def _build_weight_dict(weights, number_dict):
        return {key: weight for key, weight in zip(number_dict.keys(), weights)}
